import SwiftUI
import UIKit

struct DashMascotView: View {
    var height: CGFloat = 180
    var cornerRadius: CGFloat = 24

    var body: some View {
        Group {
            if let data = Data(base64Encoded: DashMascotAsset.base64),
               let image = UIImage(data: data) {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFit()
            } else {
                ZStack {
                    RoundedRectangle(cornerRadius: cornerRadius)
                        .fill(Color.fillMeGreen.opacity(0.12))
                    Image(systemName: "drop.fill")
                        .font(.system(size: height * 0.35, weight: .black))
                        .foregroundStyle(Color.fillMeGreen)
                }
            }
        }
        .frame(maxWidth: .infinity)
        .frame(height: height)
        .clipShape(RoundedRectangle(cornerRadius: cornerRadius))
        .accessibilityLabel("Dash, the FillMeNow mascot")
    }
}

private enum DashMascotAsset {
    static let base64 = """

"""
}
